sys_variable_value.value:
(function execute(inputs, outputs) {
    try{
    const res_identity = new x_xal_idconnect.XalientUtilitiesCatalogItem().getIdentity('email',inputs.email);
    // if(res_identity.length == 0){
    //     throw `Couldn't find an identity with email address ${inputs.email}`;
    // }
    outputs.identity_id = res_identity[0]?.id;
    }
    catch(exception){
        outputs.result = 'processing_exception';
        outputs.error_message = exception;
    }

})(inputs, outputs);

